function queueCell(a,lane){const q=S().queues[a.id];return `<td class="queue-cell" data-drop-agent="${a.id}" data-drop-lane="${lane}">${q?.lane===lane?`<button class="queue-task" draggable="true" data-queue="${a.id}"><span>${icon('clock')}${t(lane)}</span><strong>${esc(l(q.text))}</strong><small>${tr('待派发计划','Planned, not dispatched')}${icon('sliders')}</small></button>`:`<button class="queue-add" data-add-queue="${a.id}" data-lane="${lane}" aria-label="${a.agent} · ${t(lane)} · ${t('newTask')}">${icon('plus')}<span>${tr('安排','Schedule')}</span></button>`}</td>`;}
function renderSchedule(){const agents=visibleAgents(),selected=selectedAgents();return frame(4,`<section class="schedule-layout"><header class="schedule-heading"><div><span class="overline">${tr('执行与计划，分开管理','EXECUTION AND PLANNING, SIDE BY SIDE')}</span><h2>${tr('全员调度','Team dispatch')}</h2><p>${tr('当前状态不会因移动计划而改变。每一行都指向一张真实卡片。','Moving a plan does not change execution state. Each row represents one card.')}</p></div>${button('new-command',t('dispatch'),'plus','button primary')}</header><div class="table-tools"><div class="selection-summary"><strong data-selection-count>${selected.length}</strong>${tr('位已选','selected')}</div><button class="button" data-action="pause-selected" data-testid="pause-selected" ${selected.length?'':'disabled'}>${icon('pause')}${t('pauseSelected')}</button><button class="button" data-action="resume-selected" ${selected.length?'':'disabled'}>${icon('play')}${t('resumeSelected')}</button><button class="button primary" data-action="selection-command" ${selected.length?'':'disabled'}>${t('dispatch')}${icon('arrow')}</button><div class="table-search">${icon('search')}<input aria-label="${tr('搜索 Agent 或任务','Search agents or tasks')}" placeholder="${tr('搜索 Agent 或任务','Search agents or tasks')}" data-table-search value="${esc(S().search)}"></div><select id="table-filter" aria-label="${tr('筛选执行状态','Filter execution state')}">${['all','running','needs','waiting','done','paused'].map(s=>`<option value="${s}" ${S().filter===s?'selected':''}>${t(s)}</option>`).join('')}</select></div><div class="table-scroll"><table class="dispatch-table"><thead><tr><th><input type="checkbox" data-select-all aria-label="${tr('选择所有可见 Agent','Select all visible agents')}" ${agents.length&&agents.every(a=>S().selection.has(a.id))?'checked':''}></th><th>Agent / ${t('workspace')}</th><th>${t('project')}</th><th>${tr('当前执行','Current execution')}</th><th>${t('next')}<span>${tr('可拖到稍后','Drag to later')}</span></th><th>${t('later')}</th><th>${tr('会话','Session')}</th></tr></thead><tbody>${agents.map(a=>`<tr data-table-row="${a.id}" class="${S().selection.has(a.id)?'selected':''}"><td>${check(a)}</td><td><div class="table-person">${av(a)}<div><strong>${a.agent}</strong><small>${spaceName(a.space)}</small></div></div></td><td><span class="project-label">${projects[a.project].name}</span><small>${a.engine}</small></td><td><button class="table-work" data-chat="${a.id}">${esc(l(a.title))}</button><div class="table-status">${status(a)}<small>${a.progress}/${a.total} ${t('steps')}</small></div></td>${queueCell(a,'next')}${queueCell(a,'later')}<td><button class="icon-button" data-chat="${a.id}" title="${t('chat')}" aria-label="${a.agent} · ${t('chat')}">${icon('chat')}</button></td></tr>`).join('')}</tbody></table>${!agents.length?`<p class="empty">${t('empty')}</p>`:''}</div><footer class="schedule-bottom"><span>${agents.length} Agent · ${tr('计划只排序，不自动派发','Plans are ordered, not automatically dispatched')}</span><span>${tr('点击计划可编辑 · 也可拖到下一列','Click a plan to edit, or drag it to the next column')}</span></footer></section>`);}
